window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["theverge"]={html:"<div class=\"own-theverge\">\n  <header class=\"tv-bar\">\n    <a class=\"tv-wordmark\" href=\"#tv-top\" aria-label=\"Northwind home\">Northwind</a>\n    <nav class=\"tv-nav\" aria-label=\"Primary\">\n      <a href=\"#tv-stream\">Stream</a>\n      <a href=\"#tv-tech\">Tech</a>\n      <a href=\"#tv-ops\">Ops</a>\n      <a href=\"#tv-reviews\">Reviews</a>\n    </nav>\n    <div class=\"tv-bar-right\">\n      <button class=\"tv-search\" type=\"button\" aria-label=\"Search\">\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n      </button>\n      <a class=\"tv-btn tv-btn-mint\" href=\"#tv-join\">Subscribe</a>\n    </div>\n  </header>\n\n  <section class=\"tv-mast\" id=\"tv-top\" aria-labelledby=\"tv-mast-h\">\n    <p class=\"tv-whisper\">Operations &middot; analytics &middot; the desk</p>\n    <h1 id=\"tv-mast-h\" class=\"tv-giant\">Northwind</h1>\n    <p class=\"tv-mast-deck\">Loud, live coverage of the systems moving your region &mdash; throughput, refunds, latency, and the people shipping it all.</p>\n  </section>\n\n  <section class=\"tv-top-story\" aria-labelledby=\"tv-top-h\">\n    <article class=\"tv-feature\">\n      <div class=\"tv-feature-art\" aria-hidden=\"true\">\n        <span class=\"tv-hazard\"></span>\n        <span class=\"tv-bars\"><i></i><i></i><i></i><i></i><i></i></span>\n      </div>\n      <div class=\"tv-feature-body\">\n        <span class=\"tv-tag tv-tag-mint\">Lead story</span>\n        <h2 id=\"tv-top-h\">The throughput wall is finally coming down</h2>\n        <p>Three regions, one dashboard, and the quiet rewrite that cut latency to 82 milliseconds across every storefront.</p>\n        <span class=\"tv-byline\">By R. Okonkwo &middot; 12 min read</span>\n      </div>\n    </article>\n    <aside class=\"tv-side\">\n      <a class=\"tv-side-item\" href=\"#tv-stream\">\n        <span class=\"tv-mono\">09:41</span>\n        <span class=\"tv-side-h\">Refunds fall under one percent</span>\n      </a>\n      <a class=\"tv-side-item\" href=\"#tv-stream\">\n        <span class=\"tv-mono\">08:15</span>\n        <span class=\"tv-side-h\">A new region joins the stream</span>\n      </a>\n      <a class=\"tv-side-item\" href=\"#tv-stream\">\n        <span class=\"tv-mono\">07:02</span>\n        <span class=\"tv-side-h\">Inside the tabular-figure redesign</span>\n      </a>\n    </aside>\n  </section>\n\n  <section class=\"tv-stream\" id=\"tv-stream\" aria-labelledby=\"tv-stream-h\">\n    <div class=\"tv-stream-head\">\n      <h2 id=\"tv-stream-h\" class=\"tv-stream-title\">The StoryStream</h2>\n      <p class=\"tv-whisper\">Latest first &middot; mono on the rail</p>\n    </div>\n    <ol class=\"tv-feed\">\n      <li class=\"tv-item\">\n        <span class=\"tv-stamp\">14:02</span>\n        <article class=\"tv-card tv-card-outline\">\n          <span class=\"tv-kicker\">Platform</span>\n          <h3>The edge cache that learned to count orders</h3>\n          <p>Every regional hop now carries its own counter, and the totals finally agree.</p>\n        </article>\n      </li>\n      <li class=\"tv-item\">\n        <span class=\"tv-stamp\">13:26</span>\n        <article class=\"tv-card tv-card-mint\">\n          <span class=\"tv-kicker tv-kicker-dark\">Hazard mint</span>\n          <h3>Subscribe and get the operations stream early</h3>\n          <p>A daily dig on the metrics, the outages, and the rebuilds behind every region.</p>\n          <a class=\"tv-btn tv-btn-dark\" href=\"#tv-join\">Join the stream</a>\n        </article>\n      </li>\n      <li class=\"tv-item\">\n        <span class=\"tv-stamp\">12:40</span>\n        <article class=\"tv-card tv-card-outline\">\n          <span class=\"tv-kicker\">Analysis</span>\n          <h3>Why every ops team is suddenly running a monospace typeface</h3>\n          <p>Tabular figures aren't nostalgia. They're how a ledger stays honest at 3 a.m.</p>\n        </article>\n      </li>\n      <li class=\"tv-item\">\n        <span class=\"tv-stamp\">11:58</span>\n        <article class=\"tv-card tv-card-violet\">\n          <span class=\"tv-kicker tv-kicker-light\">Ultraviolet</span>\n          <h3>The rebuild that took throughput from 29k to 61k</h3>\n          <p>One region, one quarter, and a pipeline that stopped apologising for itself.</p>\n          <a class=\"tv-btn tv-btn-outline\" href=\"#tv-reviews\">Read the teardown</a>\n        </article>\n      </li>\n      <li class=\"tv-item\">\n        <span class=\"tv-stamp\">10:11</span>\n        <article class=\"tv-card tv-card-outline\">\n          <span class=\"tv-kicker\">Ops desk</span>\n          <h3>A field guide to the 82-millisecond query</h3>\n          <p>What a healthy latency budget looks like when four regions hit the same table.</p>\n        </article>\n      </li>\n    </ol>\n  </section>\n\n  <section class=\"tv-tiles\" id=\"tv-tech\" aria-labelledby=\"tv-tiles-h\">\n    <h2 id=\"tv-tiles-h\" class=\"tv-sec-title\">Elsewhere on the desk</h2>\n    <div class=\"tv-tile-grid\">\n      <article class=\"tv-tile tv-tile-yellow\">\n        <span class=\"tv-kicker tv-kicker-dark\">Hardware</span>\n        <h3>The counter-top terminal nobody asked for</h3>\n        <p>And why every store now wants one.</p>\n      </article>\n      <article class=\"tv-tile tv-tile-outline\">\n        <span class=\"tv-kicker\">Software</span>\n        <h3>The dashboard that hides its own settings</h3>\n        <p>Configuration as a last resort.</p>\n      </article>\n      <article class=\"tv-tile tv-tile-mint\">\n        <span class=\"tv-kicker tv-kicker-dark\">Review</span>\n        <h3>Northwind Model X, reviewed</h3>\n        <p>Fast, quiet, and allergic to gradients.</p>\n      </article>\n      <article class=\"tv-tile tv-tile-outline\">\n        <span class=\"tv-kicker\">Science</span>\n        <h3>What four regions taught us about queues</h3>\n        <p>Throughput is a feeling until it isn't.</p>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"tv-slate\" id=\"tv-reviews\" aria-labelledby=\"tv-slate-h\">\n    <div class=\"tv-slate-copy\">\n      <p class=\"tv-whisper tv-whisper-mint\">By the numbers</p>\n      <h2 id=\"tv-slate-h\">This quarter, flat and loud</h2>\n      <p class=\"tv-serif\">The Verge-style lede, but for operators: no soft shadows, no washes, just borders and saturated tiles doing the work a gradient would do anywhere else.</p>\n    </div>\n    <div class=\"tv-stats\">\n      <div class=\"tv-stat\"><b>184,904</b><span>Orders per day</span></div>\n      <div class=\"tv-stat\"><b>99.98%</b><span>Uptime</span></div>\n      <div class=\"tv-stat\"><b>82 ms</b><span>Median latency</span></div>\n      <div class=\"tv-stat\"><b>4</b><span>Regions live</span></div>\n    </div>\n  </section>\n\n  <section class=\"tv-join\" id=\"tv-join\" aria-labelledby=\"tv-join-h\">\n    <h2 id=\"tv-join-h\">Join the stream</h2>\n    <p class=\"tv-serif\">One daily issue. Operations, outages, and the numbers behind them.</p>\n    <form class=\"tv-form\" action=\"#\" method=\"get\">\n      <label class=\"tv-visually-hidden\" for=\"tv-email\">Email address</label>\n      <input class=\"tv-input\" id=\"tv-email\" type=\"email\" name=\"email\" placeholder=\"you@region.northwind\" autocomplete=\"email\">\n      <button class=\"tv-btn tv-btn-mint\" type=\"submit\">Subscribe</button>\n    </form>\n    <p class=\"tv-form-fine\">Sample form &mdash; showcase only, nothing is sent.</p>\n  </section>\n\n  <footer class=\"tv-foot\">\n    <div class=\"tv-foot-grid\">\n      <div class=\"tv-foot-brand\">\n        <span class=\"tv-foot-word\">Northwind</span>\n        <p>Operations analytics for every region. Sample data, showcase only.</p>\n      </div>\n      <nav class=\"tv-foot-col\" aria-label=\"Sections\"><h4>Stream</h4><a href=\"#tv-stream\">Latest</a><a href=\"#tv-tech\">Tech</a><a href=\"#tv-reviews\">Reviews</a></nav>\n      <nav class=\"tv-foot-col\" aria-label=\"Company\"><h4>Company</h4><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></nav>\n      <nav class=\"tv-foot-col\" aria-label=\"Legal\"><h4>Legal</h4><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></nav>\n    </div>\n    <div class=\"tv-foot-row\">\n      <span class=\"tv-mono\">&copy; 2026 NORTHWIND &mdash; FICTIONAL BRAND</span>\n      <span class=\"tv-foot-social\" aria-label=\"Social\"><a href=\"#\" aria-label=\"X\">X</a><a href=\"#\" aria-label=\"RSS\">RSS</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ THE VERGE — own layout for showcase.html ══════════════════════════════\n   Near-black editorial canvas, acid-mint / ultraviolet hazard accents, a heavy\n   display wordmark, rounded pill cards, saturated colour-block story tiles, and\n   the StoryStream timeline rail. Depth is 1px borders and colour, never shadow;\n   mono is always UPPERCASE. Scoped under `.own-theverge`; responsive via\n   @container frame. */\n\n.own-theverge {\n  --tv-canvas: #131313;\n  --tv-slate: #2d2d2d;\n  --tv-frame: #313131;\n  --tv-white: #ffffff;\n  --tv-black: #000000;\n  --tv-mint: #3cffd0;\n  --tv-mint-border: #309875;\n  --tv-violet: #5200ff;\n  --tv-purple-rule: #3d00bf;\n  --tv-link: #3860be;\n  --tv-focus: #1eaedb;\n  --tv-text-2: #949494;\n  --tv-muted: #e9e9e9;\n\n  --tv-display: 'Manuka', Impact, Helvetica, sans-serif;\n  --tv-sans: 'PolySans', Helvetica, Arial, sans-serif;\n  --tv-mono: 'PolySans Mono', \"Courier New\", Courier, monospace;\n  --tv-serif: 'FK Roman Standard', Georgia, \"Times New Roman\", serif;\n\n  --tv-r-tag: 2px;\n  --tv-r-img: 3px;\n  --tv-r-card: 20px;\n  --tv-r-feature: 24px;\n  --tv-r-btn: 24px;\n  --tv-r-outline: 40px;\n\n  position: relative;\n  background: var(--tv-canvas);\n  color: var(--tv-white);\n  font-family: var(--tv-sans);\n  font-size: 16px;\n  line-height: 1.6;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n  border-radius: 13px;\n  overflow: clip;\n}\n\n.own-theverge *,\n.own-theverge *::before,\n.own-theverge *::after { box-sizing: border-box; }\n\n.own-theverge :focus-visible { outline: 2px solid var(--tv-mint); outline-offset: 2px; border-radius: var(--tv-r-tag); }\n\n.own-theverge h1, .own-theverge h2, .own-theverge h3, .own-theverge h4 { margin: 0; }\n.own-theverge p { margin: 0; }\n.own-theverge a { color: inherit; text-decoration: none; }\n.own-theverge a:hover { color: var(--tv-link); }\n.own-theverge .tv-visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n\n.own-theverge .tv-mono,\n.own-theverge .tv-stamp { font-family: var(--tv-mono); font-weight: 600; text-transform: uppercase; letter-spacing: 1.5px; }\n.own-theverge .tv-whisper {\n  font-family: var(--tv-sans); font-weight: 300; font-size: 19px; letter-spacing: 1.9px;\n  text-transform: uppercase; color: var(--tv-muted);\n}\n.own-theverge .tv-whisper-mint { color: var(--tv-mint); }\n.own-theverge .tv-kicker {\n  display: inline-block; font-family: var(--tv-mono); font-size: 11px; font-weight: 600;\n  letter-spacing: 1.8px; text-transform: uppercase; color: var(--tv-mint); margin-bottom: 10px;\n}\n.own-theverge .tv-kicker-dark { color: var(--tv-black); }\n.own-theverge .tv-kicker-light { color: rgba(255, 255, 255, .85); }\n.own-theverge .tv-serif { font-family: var(--tv-serif); font-weight: 400; letter-spacing: -.16px; line-height: 1.3; }\n\n/* ── buttons — mint pill, slate pill, outlined mint ───────────────────────── */\n.own-theverge .tv-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--tv-mono); font-weight: 600; font-size: 12px; letter-spacing: 1.5px;\n  text-transform: uppercase; padding: 10px 24px; border-radius: var(--tv-r-btn);\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap; line-height: 1.6;\n  transition: background-color .18s ease, color .18s ease, box-shadow .18s ease;\n}\n.own-theverge .tv-btn-mint { background: var(--tv-mint); color: var(--tv-black); }\n.own-theverge .tv-btn-mint:hover { background: rgba(255, 255, 255, .2); color: var(--tv-black); box-shadow: 0 0 0 1px #c2c2c2; }\n.own-theverge .tv-btn-dark { background: var(--tv-slate); color: var(--tv-muted); }\n.own-theverge .tv-btn-dark:hover { background: rgba(255, 255, 255, .2); color: var(--tv-black); box-shadow: 0 0 0 1px #c2c2c2; }\n.own-theverge .tv-btn-outline { background: transparent; color: var(--tv-mint); border-color: var(--tv-mint); border-radius: var(--tv-r-outline); }\n.own-theverge .tv-btn-outline:hover { background: var(--tv-mint); color: var(--tv-black); }\n\n/* ── nav ──────────────────────────────────────────────────────────────────── */\n.own-theverge .tv-bar {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 24px;\n  padding: 12px 32px; background: rgba(19, 19, 19, .94);\n  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);\n  border-bottom: 1px solid var(--tv-frame);\n}\n.own-theverge .tv-wordmark {\n  font-family: var(--tv-display); font-weight: 900; font-size: 26px; text-transform: uppercase;\n  letter-spacing: 1.07px; line-height: 1; color: #fff;\n}\n.own-theverge .tv-nav { display: flex; align-items: center; gap: 22px; margin-left: 8px; }\n.own-theverge .tv-nav a {\n  font-family: var(--tv-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.8px;\n  text-transform: uppercase; color: var(--tv-muted); padding: 4px 0;\n}\n.own-theverge .tv-nav a:hover { color: var(--tv-link); }\n.own-theverge .tv-nav a:first-child { box-shadow: inset 0 -1px 0 0 var(--tv-mint); }\n.own-theverge .tv-bar-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-theverge .tv-search {\n  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%;\n  border: 1px solid var(--tv-frame); background: transparent; cursor: pointer;\n}\n.own-theverge .tv-search svg { width: 17px; height: 17px; fill: none; stroke: #fff; stroke-width: 2; }\n.own-theverge .tv-search:hover { border-color: var(--tv-mint); }\n\n/* ── masthead ─────────────────────────────────────────────────────────────── */\n.own-theverge .tv-mast { padding: 56px 32px 40px; border-bottom: 1px solid var(--tv-frame); }\n.own-theverge .tv-giant {\n  font-family: var(--tv-display); font-weight: 900; font-size: clamp(64px, 11cqi, 107px);\n  line-height: .95; text-transform: uppercase; letter-spacing: 1.07px; color: #fff;\n  margin: 14px 0 18px;\n}\n.own-theverge .tv-mast-deck { font-family: var(--tv-serif); font-size: 20px; line-height: 1.35; color: var(--tv-muted); max-width: 54ch; }\n\n/* ── top story ────────────────────────────────────────────────────────────── */\n.own-theverge .tv-top-story { display: grid; grid-template-columns: 1.5fr 1fr; gap: 24px; padding: 40px 32px; }\n.own-theverge .tv-feature {\n  display: grid; grid-template-rows: auto 1fr; border: 1px solid #fff; border-radius: var(--tv-r-feature);\n  overflow: hidden;\n}\n.own-theverge .tv-feature-art {\n  position: relative; min-height: 220px; background: var(--tv-canvas);\n  display: flex; align-items: flex-end; gap: 14px; padding: 24px; overflow: hidden;\n}\n.own-theverge .tv-feature-art .tv-hazard {\n  position: absolute; inset: 0;\n  background: repeating-linear-gradient(135deg, var(--tv-mint) 0 22px, var(--tv-canvas) 22px 44px);\n  opacity: .16;\n}\n.own-theverge .tv-bars { position: relative; display: flex; align-items: flex-end; gap: 12px; height: 140px; }\n.own-theverge .tv-bars i { display: block; width: 26px; border-radius: 4px 4px 0 0; background: var(--tv-mint); }\n.own-theverge .tv-bars i:nth-child(1) { height: 42%; }\n.own-theverge .tv-bars i:nth-child(2) { height: 66%; }\n.own-theverge .tv-bars i:nth-child(3) { height: 88%; background: var(--tv-violet); }\n.own-theverge .tv-bars i:nth-child(4) { height: 54%; }\n.own-theverge .tv-bars i:nth-child(5) { height: 74%; }\n.own-theverge .tv-feature-body { padding: 26px 28px; }\n.own-theverge .tv-feature-body h2 {\n  font-family: var(--tv-sans); font-weight: 700; font-size: 34px; line-height: 1; letter-spacing: 0;\n  color: #fff; margin: 6px 0 12px;\n}\n.own-theverge .tv-feature-body p { font-family: var(--tv-sans); font-weight: 500; font-size: 16px; line-height: 1.6; color: var(--tv-muted); margin-bottom: 16px; }\n.own-theverge .tv-byline { font-family: var(--tv-sans); font-size: 11px; letter-spacing: 1.1px; text-transform: uppercase; color: var(--tv-text-2); }\n.own-theverge .tv-side { display: flex; flex-direction: column; gap: 14px; }\n.own-theverge .tv-side-item {\n  display: grid; gap: 6px; padding: 18px 20px; border: 1px solid var(--tv-frame); border-radius: var(--tv-r-card);\n}\n.own-theverge .tv-side-item:hover { border-color: var(--tv-mint); }\n.own-theverge .tv-side-item .tv-mono { font-size: 11px; color: var(--tv-mint); }\n.own-theverge .tv-side-h { font-family: var(--tv-sans); font-weight: 700; font-size: 20px; line-height: 1; color: #fff; }\n\n/* ── StoryStream ──────────────────────────────────────────────────────────── */\n.own-theverge .tv-stream { padding: 48px 32px; }\n.own-theverge .tv-stream-head { margin-bottom: 30px; }\n.own-theverge .tv-stream-title {\n  font-family: var(--tv-sans); font-weight: 700; font-size: 34px; line-height: 1; letter-spacing: 0;\n  color: #fff; margin-bottom: 8px;\n}\n.own-theverge .tv-feed { list-style: none; margin: 0; padding: 0; position: relative; }\n.own-theverge .tv-item {\n  position: relative; display: grid; grid-template-columns: 84px 1fr; gap: 20px;\n  padding: 0 0 16px 0;\n}\n.own-theverge .tv-item::before {\n  content: ''; position: absolute; left: 96px; top: 8px; bottom: -8px; width: 0;\n  border-left: 1px dashed var(--tv-purple-rule);\n}\n.own-theverge .tv-item:last-child::before { display: none; }\n.own-theverge .tv-stamp { font-size: 11px; font-weight: 500; letter-spacing: 1.1px; color: var(--tv-text-2); padding-top: 6px; }\n.own-theverge .tv-card {\n  position: relative; border-radius: var(--tv-r-card); padding: 24px 26px;\n  border: 1px solid #fff; background: var(--tv-canvas);\n}\n.own-theverge .tv-card h3 {\n  font-family: var(--tv-sans); font-weight: 700; font-size: 24px; line-height: 1; letter-spacing: 0;\n  color: #fff; margin-bottom: 10px; transition: color .15s ease;\n}\n.own-theverge .tv-card:hover h3 { color: var(--tv-link); }\n.own-theverge .tv-card p { font-size: 13px; font-weight: 400; line-height: 1.6; color: var(--tv-text-2); }\n.own-theverge .tv-card .tv-btn { margin-top: 16px; }\n.own-theverge .tv-card-mint { background: var(--tv-mint); border-color: var(--tv-mint-border); }\n.own-theverge .tv-card-mint h3 { color: var(--tv-black); }\n.own-theverge .tv-card-mint p { color: rgba(0, 0, 0, .72); }\n.own-theverge .tv-card-mint:hover h3 { color: var(--tv-black); }\n.own-theverge .tv-card-violet { background: rgba(82, 0, 255, .9); border-color: var(--tv-violet); }\n.own-theverge .tv-card-violet h3, .own-theverge .tv-card-violet p { color: #fff; }\n.own-theverge .tv-card-violet:hover h3 { color: var(--tv-link); }\n\n/* ── tile grid ────────────────────────────────────────────────────────────── */\n.own-theverge .tv-tiles { padding: 48px 32px; border-top: 1px solid var(--tv-frame); }\n.own-theverge .tv-sec-title { font-family: var(--tv-sans); font-weight: 700; font-size: 34px; line-height: 1; color: #fff; margin-bottom: 26px; }\n.own-theverge .tv-tile-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-theverge .tv-tile {\n  border-radius: var(--tv-r-card); padding: 22px; min-height: 200px;\n  display: flex; flex-direction: column; border: 1px solid #fff; background: var(--tv-canvas);\n}\n.own-theverge .tv-tile h3 { font-family: var(--tv-sans); font-weight: 700; font-size: 20px; line-height: 1; color: #fff; margin-bottom: 8px; }\n.own-theverge .tv-tile p { font-size: 13px; color: var(--tv-text-2); margin-top: auto; }\n.own-theverge .tv-tile-yellow { background: #ffdb13; border-color: #ffdb13; }\n.own-theverge .tv-tile-yellow h3 { color: var(--tv-black); }\n.own-theverge .tv-tile-yellow p { color: rgba(0, 0, 0, .7); }\n.own-theverge .tv-tile-mint { background: var(--tv-mint); border-color: var(--tv-mint-border); }\n.own-theverge .tv-tile-mint h3 { color: var(--tv-black); }\n.own-theverge .tv-tile-mint p { color: rgba(0, 0, 0, .7); }\n\n/* ── slate stats band ─────────────────────────────────────────────────────── */\n.own-theverge .tv-slate {\n  display: grid; grid-template-columns: 1fr 1.1fr; gap: 40px; align-items: center;\n  padding: 56px 32px; background: var(--tv-slate);\n}\n.own-theverge .tv-slate h2 { font-family: var(--tv-sans); font-weight: 700; font-size: 34px; line-height: 1; color: #fff; margin: 12px 0 14px; }\n.own-theverge .tv-slate .tv-serif { color: var(--tv-muted); max-width: 46ch; }\n.own-theverge .tv-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 24px 32px; }\n.own-theverge .tv-stat { display: grid; gap: 4px; }\n.own-theverge .tv-stat b { font-family: var(--tv-display); font-weight: 900; font-size: 48px; line-height: .95; color: var(--tv-mint); letter-spacing: 0; }\n.own-theverge .tv-stat span { font-family: var(--tv-mono); font-size: 11px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: var(--tv-muted); }\n\n/* ── join ─────────────────────────────────────────────────────────────────── */\n.own-theverge .tv-join {\n  padding: 64px 32px; text-align: center; background: var(--tv-canvas);\n  border-top: 1px solid var(--tv-frame); border-bottom: 1px solid var(--tv-frame);\n}\n.own-theverge .tv-join h2 { font-family: var(--tv-display); font-weight: 900; font-size: clamp(40px, 5cqi, 60px); line-height: 1; text-transform: uppercase; letter-spacing: 1.07px; color: #fff; margin-bottom: 14px; }\n.own-theverge .tv-join .tv-serif { color: var(--tv-muted); max-width: 48ch; margin: 0 auto 26px; font-size: 20px; }\n.own-theverge .tv-form { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; max-width: 560px; margin: 0 auto; }\n.own-theverge .tv-input {\n  flex: 1; min-width: 220px; font-family: var(--tv-sans); font-size: 15px; color: #fff;\n  background: var(--tv-canvas); border: 1px solid var(--tv-text-2); border-radius: var(--tv-r-tag);\n  padding: 12px 14px; transition: border-color .15s ease;\n}\n.own-theverge .tv-input::placeholder { color: var(--tv-text-2); }\n.own-theverge .tv-input:focus { outline: none; border-color: var(--tv-mint); }\n.own-theverge .tv-form-fine { font-family: var(--tv-mono); font-size: 11px; letter-spacing: 1.1px; text-transform: uppercase; color: var(--tv-text-2); margin-top: 16px; }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-theverge .tv-foot { padding: 56px 32px 32px; }\n.own-theverge .tv-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 32px; }\n.own-theverge .tv-foot-word { font-family: var(--tv-display); font-weight: 900; font-size: 30px; text-transform: uppercase; letter-spacing: 1.07px; color: #fff; }\n.own-theverge .tv-foot-brand p { font-size: 13px; color: var(--tv-text-2); margin-top: 12px; max-width: 32ch; line-height: 1.6; }\n.own-theverge .tv-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-theverge .tv-foot-col h4 { font-family: var(--tv-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.8px; text-transform: uppercase; color: var(--tv-mint); }\n.own-theverge .tv-foot-col a { font-size: 14px; color: var(--tv-muted); }\n.own-theverge .tv-foot-col a:hover { color: var(--tv-link); }\n.own-theverge .tv-foot-row {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; align-items: center;\n  margin-top: 40px; padding-top: 20px; border-top: 1px solid var(--tv-frame);\n}\n.own-theverge .tv-foot-row .tv-mono { font-size: 11px; letter-spacing: 1.5px; color: var(--tv-text-2); }\n.own-theverge .tv-foot-social { display: flex; gap: 12px; }\n.own-theverge .tv-foot-social a {\n  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%;\n  border: 1px solid var(--tv-frame); font-family: var(--tv-mono); font-size: 11px; font-weight: 600;\n  letter-spacing: 1.1px; color: var(--tv-muted);\n}\n.own-theverge .tv-foot-social a:hover { border-color: var(--tv-mint); color: var(--tv-mint); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-theverge .tv-nav { display: none; }\n  .own-theverge .tv-top-story { grid-template-columns: 1fr; }\n  .own-theverge .tv-tile-grid { grid-template-columns: 1fr 1fr; }\n  .own-theverge .tv-slate { grid-template-columns: 1fr; gap: 28px; }\n  .own-theverge .tv-foot-grid { grid-template-columns: 1fr 1fr 1fr; gap: 24px; }\n}\n@container frame (max-width: 760px) {\n  .own-theverge .tv-bar { top: 10px; padding: 10px 16px; }\n  .own-theverge .tv-wordmark { font-size: 20px; letter-spacing: .5px; }\n  .own-theverge .tv-mast,\n  .own-theverge .tv-top-story,\n  .own-theverge .tv-stream,\n  .own-theverge .tv-tiles,\n  .own-theverge .tv-slate,\n  .own-theverge .tv-join,\n  .own-theverge .tv-foot { padding-left: 18px; padding-right: 18px; }\n  .own-theverge .tv-giant { font-size: 54px; }\n  .own-theverge .tv-feature-body h2,\n  .own-theverge .tv-stream-title,\n  .own-theverge .tv-sec-title,\n  .own-theverge .tv-slate h2 { font-size: 26px; }\n  .own-theverge .tv-tile-grid { grid-template-columns: 1fr; }\n  .own-theverge .tv-stats { grid-template-columns: 1fr 1fr; }\n  .own-theverge .tv-foot-grid { grid-template-columns: 1fr 1fr; }\n  .own-theverge .tv-item { grid-template-columns: 1fr; gap: 8px; padding-bottom: 18px; }\n  .own-theverge .tv-item::before { display: none; }\n  .own-theverge .tv-stamp { padding-top: 0; }\n}\n@container frame (max-width: 430px) {\n  .own-theverge .tv-giant { font-size: 44px; }\n  .own-theverge .tv-stat b { font-size: 38px; }\n  .own-theverge .tv-stats { grid-template-columns: 1fr; }\n  .own-theverge .tv-foot-grid { grid-template-columns: 1fr; }\n  .own-theverge .tv-btn { font-size: 11px; padding: 10px 18px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-theverge *, .own-theverge *::before, .own-theverge *::after {\n    transition-duration: .001ms !important;\n    animation-duration: .001ms !important;\n  }\n}\n"};
/* ══ THE VERGE — behaviour for showcase.html ════════════════════════════════
   Registers window.OWN_LAYOUTS['theverge'].init(root). The Verge is flat and
   colour-only, so the script just intercepts the sample subscribe form (no
   navigation away) and adds a soft reveal to the stream items. The form handler
   is bound to an AbortController and the observer disconnected on cleanup. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['theverge'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var io = null;

      var form = root.querySelector('.tv-form');
      var input = root.querySelector('.tv-input');
      if (form) {
        form.addEventListener('submit', function (e) {
          e.preventDefault();
          if (input) {
            input.value = '';
            input.placeholder = 'Subscribed \u2014 check your inbox.';
          }
        }, signal ? { signal: signal } : undefined);
      }

      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        var targets = root.querySelectorAll('.tv-item, .tv-tile, .tv-feature');
        io = new IntersectionObserver(function (entries) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) {
              entry.target.style.opacity = '1';
              entry.target.style.transform = 'none';
              io.unobserve(entry.target);
            }
          });
        }, { root: null, rootMargin: '0px 0px -6% 0px', threshold: 0.06 });

        targets.forEach(function (el) {
          el.style.opacity = '0';
          el.style.transform = 'translateY(16px)';
          el.style.transition = 'opacity .5s ease, transform .5s ease';
          io.observe(el);
        });
      }

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        if (io) { try { io.disconnect(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
